content:
:root {
  color-scheme: light dark;
  --bg: #fafafa;
  --fg: #18181b;
  --panel: #f4f4f5;
  --border: #d4d4d8;
  --accent: #2563eb;
}
.theme-dark {
  --bg: #09090b;
  --fg: #fafafa;
  --panel: #18181b;
  --border: #27272a;
  --accent: #60a5fa;
}
@media (prefers-color-scheme: dark) {
  .theme-auto {
    --bg: #09090b;
    --fg: #fafafa;
    --panel: #18181b;
    --border: #27272a;
    --accent: #60a5fa;
  }
}
* { box-sizing: border-box; }
body { margin: 0; font-family: system-ui, sans-serif; background: var(--bg); color: var(--fg); }
.app { display: grid; grid-template-columns: 240px 1fr 240px; min-height: 100vh; }
.panel { background: var(--panel); border-right: 1px solid var(--border); padding: 0.75rem; overflow: auto; }
.panel.right { border-right: 0; border-left: 1px solid var(--border); }
.center { display: grid; grid-template-rows: 1fr 1fr; min-width: 0; }
.editor header, .code-block header { display: flex; justify-content: space-between; gap: 0.5rem; padding: 0.25rem 0.5rem; }
button { cursor: pointer; }
.preview-body { padding: 1rem; overflow: auto; }
@media (prefers-reduced-motion: reduce) {
  * { transition: none !important; animation: none !important; }
}
